using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioWeldValidation
{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static int checks,phase,errors,hot;static string stage;static AnimationStudioWindow host;static MashBoxStudioViewport view;static StudioModelEditor editor;static Vector2 sent,sourcePoint,destinationPoint;static int source,destination;static Vector3[] original;static Vector3 target;static double next;static bool renderPending;static Exception renderFailure;
 static void Check(bool value,string message){if(!value)throw new Exception(stage+": "+message);checks++;}
 static object Get(string name)=>typeof(StudioModelEditor).GetField(name,F).GetValue(editor);static void Set(string name,object value)=>typeof(StudioModelEditor).GetField(name,F).SetValue(editor,value);
 static object Call(string name,params object[] args)=>typeof(StudioModelEditor).GetMethods(F).Single(m=>m.Name==name&&m.GetParameters().Length==args.Length&&m.GetParameters().Select((p,i)=>args[i]==null||p.ParameterType.IsInstanceOfType(args[i])).All(v=>v)).Invoke(editor,args);
 static void Reset(){UnityEditor.Undo.ClearAll();StudioUndo.ClearForTests();StudioUndo.IncrementCurrentGroup();}
 static void History(bool redo=false){UnityEditor.Undo.FlushUndoRecordObjects();StudioUndo.IncrementCurrentGroup();if(redo)StudioUndo.PerformRedo();else StudioUndo.PerformUndo();}
 static StudioModelDocument.Node Cube(){var mesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var polygons);return new StudioModelDocument.Node{name="Cube",mesh=mesh,cutPolygons=polygons,cutTriangles=mesh.triangles};}
 public static void Run(){Application.logMessageReceived+=(s,t,k)=>{if(k==LogType.Assert||k==LogType.Error||k==LogType.Exception)errors++;};EditorApplication.delayCall+=()=>{try{
  Geometry();var doc=ScriptableObject.CreateInstance<StudioModelDocument>();doc.nodes.Add(Cube());host=ScriptableObject.CreateInstance<AnimationStudioWindow>();typeof(AnimationStudioWindow).GetField("modelingMode",F).SetValue(host,true);typeof(AnimationStudioWindow).GetField("modelDocument",F).SetValue(host,doc);typeof(AnimationStudioWindow).GetMethod("OpenViewport",F).Invoke(host,null);view=Resources.FindObjectsOfTypeAll<MashBoxStudioViewport>().Single(v=>v.Studio==host);view.position=new Rect(100,100,1000,750);editor=(StudioModelEditor)typeof(AnimationStudioWindow).GetField("modelEditor",F).GetValue(host);editor.SelectObject(0);editor.SetToolbarComponentMode(StudioModelEditor.ComponentMode.Vertex);Set("xray",true);view.LookAtDirect(Vector3.zero,Quaternion.Euler(18,30,0),2.3f);
  Commands();editor.SetToolbarComponentMode(StudioModelEditor.ComponentMode.Object);editor.ExecuteMarkingAction(StudioModelEditor.MarkingAction.Clear,null);editor.ActivateTargetWeld();StudioModelEditor.TargetWeldInputProbe=()=>Event.current.mousePosition=sent;SceneView.duringSceneGui+=After;EditorApplication.update+=Tick;next=EditorApplication.timeSinceStartup+2;
 }catch(Exception ex){Finish(ex);}};}
 static void Geometry()
 {
  stage="center kernel";
  foreach(int count in new[]{2,3,4,24})
  {
   var node=Cube();try{var points=node.mesh.vertices;var selected=Enumerable.Range(0,Math.Min(count,points.Length)).ToArray();var unique=selected.Select(i=>points[i]).Distinct().ToArray();var center=unique.Aggregate(Vector3.zero,(a,b)=>a+b)/unique.Length;var result=new StudioMeshCuts(node).MergeVertices(node,selected,true,0,Matrix4x4.identity);Check(result!=null,"Center merge missing");Check(result.Selection.Length>0,"Center point lost");foreach(int i in result.Selection)Check((node.mesh.vertices[i]-center).sqrMagnitude<1e-10f,"Not the geometric center");Check(node.mesh.triangles.All(i=>i>=0&&i<node.mesh.vertexCount),"Invalid render index");if(count==24)Check(node.mesh.vertices.Distinct().Count()==1&&node.mesh.vertexCount==1,"Whole cube did not become one loose vertex");}finally{Object.DestroyImmediate(node.mesh);}
  }
  stage="large loose selection";var loose=new StudioModelDocument.Node{mesh=new Mesh()};loose.mesh.vertices=Enumerable.Range(0,10000).Select(i=>new Vector3(i,0,0)).ToArray();loose.mesh.triangles=Array.Empty<int>();try{var result=new StudioMeshCuts(loose).MergeVertices(loose,Enumerable.Range(0,10000),true,0,Matrix4x4.identity);Check(result.Removed==9999&&loose.mesh.vertexCount==1,"Large selection not merged to one point");Check(Math.Abs(loose.mesh.vertices[0].x-4999.5f)<.01f,"Large selection wrong center");}finally{Object.DestroyImmediate(loose.mesh);}
  stage="target kernel and attributes";var weld=Cube();try{var positions=weld.mesh.vertices;var colors=positions.Select((p,i)=>new Color(i/30f,.2f,.5f,1)).ToArray();weld.mesh.colors=colors;for(int c=0;c<8;c++){var uv=positions.Select((p,i)=>new Vector4(i*.02f,c,.3f,.4f)).ToList();if(c%3==0)weld.mesh.SetUVs(c,uv.Select(p=>new Vector2(p.x,p.y)).ToList());else if(c%3==1)weld.mesh.SetUVs(c,uv.Select(p=>new Vector3(p.x,p.y,p.z)).ToList());else weld.mesh.SetUVs(c,uv);}var result=new StudioMeshCuts(weld).MergeVertices(weld,new[]{0,1},true,0,Matrix4x4.identity,target:1);Check(result!=null,"Target weld missing");foreach(int i in result.Selection)Check(weld.mesh.vertices[i].Equals(positions[1]),"Destination moved");Check(!weld.mesh.vertices.Contains(positions[0]),"Source not welded");Check(weld.mesh.colors.Length==weld.mesh.vertexCount,"Colors lost");for(int c=0;c<8;c++)Check(weld.mesh.GetVertexAttributeDimension((UnityEngine.Rendering.VertexAttribute)((int)UnityEngine.Rendering.VertexAttribute.TexCoord0+c))==2+c%3,"UV dimension changed");Check(weld.mesh.triangles.All(i=>i>=0&&i<weld.mesh.vertexCount),"Bad target render index");}finally{Object.DestroyImmediate(weld.mesh);}
 }
 static void Commands()
 {
  stage="menu and M command";var menu=new StudioMenu("Mesh Tools");Call("PopulateModelMenu","Mesh Tools",menu,view,(Action<StudioModelDocument>)(_=>{}));Check(menu.Items.Count(i=>i.Text=="Merge to Center")==1&&menu.Items.Count(i=>i.Text=="Target Weld")==1,"Missing separate commands");Check(!menu.Items.Any(i=>i.Text=="Merge Vertices"),"Old merge entry retained");var id=menu.Items.Single(i=>i.Text=="Merge to Center").Command.Value;Check(id==StudioModelCommands.StableId("Mesh Tools/Merge Vertices"),"Legacy command identity changed");StudioShortcuts.Reset(id);Check(StudioShortcuts.Bindings(id).Any(b=>b.key==KeyCode.M&&b.modifiers==StudioModifiers.None),"M is not the default");Check(StudioModelCommands.Find(id).name=="Merge to Center","Preferences label stale");
  editor.Components.UnionWith(new[]{0,1,2});original=editor.Document.nodes[0].mesh.vertices;var center=original.Take(3).Aggregate(Vector3.zero,(a,b)=>a+b)/3;Reset();menu=new StudioMenu("Mesh Tools");Call("PopulateModelMenu","Mesh Tools",menu,view,(Action<StudioModelDocument>)(_=>{}));menu.Items.Single(i=>i.Text=="Merge to Center").Action();Check(StudioUndo.RetainedActions==1,"Center command not one action");Check(editor.Components.Count>0&&editor.Components.All(i=>(editor.Document.nodes[0].mesh.vertices[i]-center).sqrMagnitude<1e-10f),"Center command used a distance threshold");History();Check(original.SequenceEqual(editor.Document.nodes[0].mesh.vertices)&&editor.Components.SetEquals(new[]{0,1,2}),"Center Undo lost mesh/selection");History(true);Check(!original.SequenceEqual(editor.Document.nodes[0].mesh.vertices),"Center Redo failed");History();
  StudioShortcuts.Set(id,Array.Empty<StudioShortcuts.Binding>());Check(StudioShortcuts.Bindings(id).Length==0,"Explicit unassignment ignored");StudioShortcuts.Reset(id);
 }
 static void After(SceneView scene)
 {
  if(scene!=view)return;hot=GUIUtility.hotControl;if(Event.current.type==EventType.Repaint&&renderPending){renderPending=false;try{Render();}catch(Exception ex){renderFailure=ex;}}
  if(Event.current.type==EventType.Repaint&&phase==0)
  {
   var points=editor.Document.nodes[0].mesh.vertices;source=Enumerable.Range(0,points.Length).OrderBy(i=>HandleUtility.WorldToGUIPoint(editor.Transforms[0].TransformPoint(points[i])).x).Last();var face=new StudioMeshCuts(editor.Document.nodes[0]).Faces.First(f=>f.Vertices.Contains(source));destination=face.Vertices[(face.Vertices.IndexOf(source)+1)%face.Vertices.Count];sourcePoint=HandleUtility.WorldToGUIPoint(editor.Transforms[0].TransformPoint(points[source]))+Vector2.right*4;destinationPoint=HandleUtility.WorldToGUIPoint(editor.Transforms[0].TransformPoint(points[destination]));
  }
 }
 static void Send(EventType type,Vector2 point,KeyCode key=KeyCode.None){var previous=sent;sent=point;view.SendEvent(new Event{type=type,button=0,keyCode=key,mousePosition=new Vector2(500,350),delta=point-previous});}
 static void Tick()
 {
  if(EditorApplication.timeSinceStartup<next)return;
  try
  {
   if(phase==0){stage="native target weld";Send(EventType.Layout,new Vector2(500,350));Send(EventType.Repaint,new Vector2(500,350));original=editor.Document.nodes[0].mesh.vertices;target=original[destination];Reset();Send(EventType.MouseMove,sourcePoint);Send(EventType.Layout,sourcePoint);Send(EventType.MouseDown,sourcePoint);Check(hot!=0&&(int)Get("targetWeldSource")>=0,"Source click did not capture");Check(!(bool)Get("marquee"),"Weld started marquee");Check(StudioUndo.RetainedActions==0,"Source click registered geometry history");Send(EventType.MouseDrag,destinationPoint);Send(EventType.Layout,destinationPoint);renderPending=true;Send(EventType.Repaint,destinationPoint);Check(!renderPending&&renderFailure==null,"Render failed: "+renderFailure);int picked=(int)Get("targetWeldDestination");Check(picked>=0&&original[picked].Equals(target),"Drag did not snap to destination");Check(original.SequenceEqual(editor.Document.nodes[0].mesh.vertices),"Drag preview changed topology before release");Send(EventType.MouseUp,destinationPoint);Check(hot==0&&editor.Components.Count>0,"Release did not commit/release capture");Check(editor.Components.All(i=>editor.Document.nodes[0].mesh.vertices[i].Equals(target)),"Weld moved destination");Check(StudioUndo.RetainedActions==1,"Weld created extra history steps");Check((bool)Get("targetWeldActive"),"Weld exited tool instead of staying active");History();Check(original.SequenceEqual(editor.Document.nodes[0].mesh.vertices),"Target weld Undo failed");History(true);Check(editor.Components.All(i=>editor.Document.nodes[0].mesh.vertices[i].Equals(target)),"Target weld Redo failed");History();phase=1;return;}
   if(phase==1){stage="cancel and outside release";Reset();Send(EventType.Layout,sourcePoint);Send(EventType.MouseDown,sourcePoint);Send(EventType.MouseDrag,destinationPoint);Send(EventType.KeyDown,destinationPoint,KeyCode.Escape);Check(hot==0&&(int)Get("targetWeldSource")==-1&&(bool)Get("targetWeldActive"),"Escape did not cancel drag while retaining tool");Check(original.SequenceEqual(editor.Document.nodes[0].mesh.vertices)&&StudioUndo.RetainedActions==0,"Cancel modified geometry/history");Send(EventType.MouseUp,destinationPoint);Send(EventType.Layout,sourcePoint);Send(EventType.MouseDown,sourcePoint);Send(EventType.MouseDrag,new Vector2(-100,-100));Send(EventType.MouseUp,new Vector2(-100,-100));Check(hot==0&&original.SequenceEqual(editor.Document.nodes[0].mesh.vertices),"Outside release did not cancel");Send(EventType.KeyDown,sourcePoint,KeyCode.Escape);Check(!(bool)Get("targetWeldActive"),"Second Escape did not exit tool");editor.ActivateTargetWeld();editor.ActivateTool(Tool.Move);Check(!(bool)Get("targetWeldActive")&&editor.ToolbarToolSelected(Tool.Move),"Tool switch did not exit weld");stage="native M";editor.SelectObject(0);editor.SetToolbarComponentMode(StudioModelEditor.ComponentMode.Vertex);editor.Components.Clear();editor.Components.UnionWith(new[]{0,1,2});Reset();Send(EventType.KeyDown,sourcePoint,KeyCode.M);Check(StudioUndo.RetainedActions==1&&!original.SequenceEqual(editor.Document.nodes[0].mesh.vertices),"M did not merge in one action");History();Check(original.SequenceEqual(editor.Document.nodes[0].mesh.vertices),"M Undo failed");Check(errors==0,"Unexpected Unity errors: "+errors);Finish(null);}
  }catch(Exception ex){Finish(ex);}
 }
 static void Render()
 {
  var rt=new RenderTexture(640,480,24);rt.Create();var old=RenderTexture.active;var previous=view.camera.targetTexture;var rect=view.camera.pixelRect;GL.PushMatrix();try{view.camera.targetTexture=rt;view.camera.pixelRect=new Rect(0,0,640,480);Handles.SetCamera(new Rect(0,0,640,480),view.camera);RenderTexture.active=rt;GL.Clear(true,true,Color.black);GL.LoadProjectionMatrix(view.camera.projectionMatrix);GL.modelview=view.camera.worldToCameraMatrix;Call("DrawTargetWeldPreview",view);var image=new Texture2D(640,480,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,640,480),0,0);image.Apply();Check(image.GetPixels32().Count(c=>c.g>100&&c.g>c.r*1.2f)>30,"Snapped drag line did not render");var line=(Vector3[])Get("targetWeldLine");Check((line[1]-editor.Transforms[0].TransformPoint(target)).sqrMagnitude<1e-10f,"Line endpoint not on snapped vertex");File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../target-weld-preview.png")),image.EncodeToPNG());Object.DestroyImmediate(image);}finally{GL.PopMatrix();view.camera.targetTexture=previous;view.camera.pixelRect=rect;RenderTexture.active=old;Object.DestroyImmediate(rt);}
 }
 static void Finish(Exception ex){EditorApplication.update-=Tick;SceneView.duringSceneGui-=After;StudioModelEditor.TargetWeldInputProbe=null;File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../weld-result.txt")),ex==null?"PASS "+checks+" kernel, menu/M, native target-drag, render, cancellation and Undo checks":stage+"\n"+ex);EditorApplication.delayCall+=()=>{if(view)view.Close();if(host)Object.DestroyImmediate(host);EditorApplication.delayCall+=()=>EditorApplication.Exit(ex==null?0:1);};}
}
